  "Claim defense reward - {0} db": "領取防守獎勵：{0}達布隆",
  "Cleves-Mark": "克萊沃-馬克",
  "clinker rivets and roves": "搭接船板用鉚釘和墊圈",
  "Close recalled commission {0} db": "結清已撤回的委任：{0}達布隆",
  "Close the commission without claiming the bounty": "不索取賞金，了結委託",
  "Closely woven canvas holds its shape in a fresh breeze.": "緊密編織的帆佈在清新的微風中保持其形狀。",
  "Cloves drew the Portuguese to your shore. Your family mistook their appetite for a guarantee.": "丁香吸引葡萄牙人來到你的海岸。你的家人卻把他們對丁香的渴求當成了可靠的保證。",
  "CMD": "CMD",
  "Coastal canoe crews recognized your sail offshore. Market runners are already spreading word of your return.": "沿海獨木舟的船員在海上認出了你的船帆。集市信使已經把你歸來的消息傳開了。",
  "Coastal Pinnace": "近海輕帆船",
  "Coastal Surveyor": "海岸測量員",
  "coastal waters": "沿海水域",
  "Coasters call with every change of wind, but an unusual cargo can still stir the whole market.": "沿岸商船隨風向變化頻頻靠港，但一批特別的貨物仍足以攪動整個市場。",
  "Coaxes the ship through turns and closer to the wind.": "操船靈活，轉向俐落，也能迎風航行。",
  "Cod": "鱈魚",
  "Coffee first. Then bearings. Then whales.": "先喝咖啡，再測定航向，最後找鯨魚。",
  "Coir Cordage": "椰殼繩",
  "Cold": "寒冷",
  "Cold, isolation, and scurvy destroyed Saint Croix. De Monts and Poutrincourt will try again in sheltered Annapolis, relying on nearby Mi'kmaq knowledge.": "寒冷、孤立和壞血病摧毀了聖克羅伊島。德蒙茨和普特林古將依靠附近米克馬克的知識，在受保護的安納波利斯再次嘗試。",
  "Collect {0} db; attack {1}": "收集{0} DB；攻击 {1}",
  "Collect commission reward": "領取私掠賞金",
