  "Composite Recurve Bows": "複合反曲弓",
  "Concepcion endures at Penco as a military and administrative center, sustained from Peru on a frontier Spain has not subdued.": "康塞普西翁作為潘科的軍事和行政中心，在西班牙尚未征服的邊境上與秘魯保持聯繫。",
  "Concepcion is asking for powder, not ceremony.": "康塞普西翁要的是火藥，不是儀式。",
