  "CONTROLLED SPICES SURRENDERED {0}": "受管制香料已交出 {0}",
  "Cooperation as a weapon. That is a finer observation than any measurement of tooth or paw, and one our moralizing bestiaries would likely misunderstand.": "合作作為武器。這是比任何牙齒或爪子測量更精細的觀察，而我們的道德寓言可能會誤解這一點。",
  "Costly self-igniting pistols are deadly at close range and useful in a landing party.": "昂貴的輪簧式手槍近戰威力極強，也適合登陸小隊使用。",
  "COSTS": "成本",
  "Cotton and tobacco occupy the promoters, but neither feeds a hungry harbor town.": "種植園主忙著種棉花和菸草，可這兩樣都填不飽港鎮居民的肚子。",
  "COULD NOT END CURRENT VOYAGE": "無法結束目前航程",
