  "COVER": "封面",
  "craft worker": "手工藝人",
  "Cranes swing over the crowded wharf while guild clerks tally barrels, bales, and ships waiting on the tide.": "起重機在擁擠的碼頭上空擺動，行會職員清點桶、捆包和等待漲潮的船隻。",
  "cranes, locks, hoops, and sugar-mill repairs": "起重機、鎖、箍和糖廠維修",
