  "Creation and destruction from one furnace. Mark the fresh flows separately from the cultivated slopes; the island's prosperity and danger share a source.": "同一座火山既孕育也摧毀。請把新近的熔岩流與耕作山坡分別標出；這座島的繁榮與危險同出一源。",
