  "Current battery: {0}. Faster locks and longer culverins improve reload, damage, and range. Purse {1} db.": "目前岸防砲組：{0}。更快的砲機和更長的加農砲可提升裝填速度、威力與射程。費用：{1}達布隆。",
  "Current gear: {0}. Other nets offered: {1}. Purse {2} db.": "目前漁具：{0}。另有漁網可選：{1}。費用：{2}達布隆。",
  "Current harpoon: {0}. A stronger line and truer shaft improve the odds of holding a surfaced whale. Purse {1} db.": "目前魚叉：{0}。更結實的繩索和更筆直的叉桿能提高鉤住浮出水面的鯨魚的機率。費用：{1}達布隆。",
