  "DEMO": "示範版",
  "Denali rises from low country with scarcely any warning, an immense wall of snow above rivers and dark forest. Clouds crossed its middle while the summit remained in another weather.": "德納利山從低地驟然拔起，宛如聳立在河流與深色森林之上的巨大雪牆。雲層掠過山腰，峰頂卻處在另一片天候之中。",
  "denied a Papal commission": "拒絕接受教宗委託",
  "Denmark-Norway": "丹麥-挪威",
  "DEPRIVATION": "剝奪",
  "Deputy Governor": "副省長",
  "Deputy Governor {0}": "副州長{0}",
  "Destroy pirate haven": "摧毀海盜巢穴",
  "Destroyed": "被毀",
  "Dexterity, memory, and a complete absence of respect for property. I shall record the first two qualities in the formal account.": "敏捷、記憶力強，而且完全不尊重財產。我將在正式的敘述中記錄前兩個特質。",
  "Dhaulagiri appeared as an enormous white wall above the river gorge, its glaciers broken into blue steps. The valley made the summit seem almost impossibly near and impossibly high at once.": "道拉吉里峰看起來就像河谷上方的一道巨大的白色牆壁，它的冰河分裂成藍色的階梯。山谷讓山頂顯得近得近乎不可思議，同時又顯得高得不可思議。",
  "Dhow": "Dhow",
  "Diet of Worms dialogue": "沃爾姆斯帝國議會對話",
  "DIG OUT": "鑿冰脫困",
  "Diplomatic customs": "外交海關",
  "Diplomatic mission": "外交使團",
  "DIPLOMATIC MISSION ADVANCES": "外交使團進展",
  "Discover El Dorado.": "探索埃爾多拉多。",
  "Discovered {0}": "發現{0}",
  "Disease and hunger have emptied the fort. Relations with Powhatan have worsened as the English demand food the drought has made scarce for everyone.": "疾病和飢餓已經清空了堡壘。由於英國人對糧食的需求因乾旱而變得稀缺，因此與波瓦坦的關係惡化了。",
  "Dismiss": "遣散",
  "DISMISS": "遣散",
  "Dismiss {0}": "遣散 {0}",
  "Dismiss {0} crew before taking this vessel.": "接管這艘船前，請遣散{0}名船員。",
  "Distinct ship types sailed": "不同類型的船舶航行",
  "Diu kept its walls free of Portugal. Your estate was less fortunate with me.": "第烏城牆未曾落入葡萄牙人之手。至於你的家產，在我這裡可沒這麼幸運。",
  "DIVIDEND PAID": "已支付股息",
  "DIVIDENDS PAID": "已支付股息",
  "Do you think the fish smell us coming, or have they gone mercifully numb?": "你說魚是聞到我們來了，還是已經麻木得感覺不到了？",
  "Dock at the remote village of Hawaii.": "停靠在夏威夷偏遠的村莊。",
  "Dock: {0}": "停靠：{0}",
  "Does that strange bear earn its passage, or does it merely eat the provisions?": "那隻奇怪的熊真能幫上忙、配得上船上的口糧嗎？還是只會吃東西？",
  "Does your small black-and-white officer always smell so strongly of fish?": "你那位黑白相間的小軍官總是這麼一身魚腥味嗎？",
  "Doge": "威尼斯總督",
  "Doge {0}": "威尼斯總督{0}",
