  "Duke of Burgundy {0}": "勃艮地公爵 {0}",
  "durable, visible trade goods for the upriver market": "上游市場的耐用、可見的貿易商品",
  "Dust from the caravan road settles on the landing, where merchants weigh news from inland against news from the sea.": "商隊道路上的塵土落在碼頭上，商人在那裡權衡來自內陸和海上的消息。",
  "Dutch negotiated trade post": "荷蘭談判貿易站",
  "Dutch settler colony": "荷蘭殖民者殖民地",
  "DUTY {0}%": "關稅 {0}%",
  "Each day brings us nearer to {0} and the road to Mecca. I have waited years for the Hajj; I pray our passage remains safe.": "我們一天天接近{0}，也逐漸踏上通往麥加的路。我盼望朝覲多年，祈願此行平安。",
  "Eagle": "鷹",
  "EARLIER ACCOUNTS": "往期帳目",
  "EARLIER DIVIDENDS": "早期股息",
  "Earlier ledger activity ({0} entries)": "이전 원장 내역({0}건)",
  "EARLIER SHIP SALES": "早期船舶銷售",
  "EARLIER SHIPBUILDING COSTS": "早期造船成本",
  "Earlier shipyard accounts": "早期造船廠帳目",
  "Earlier Spanish footholds in Caracas failed. Losada proposes a new city, though Caracas and allied peoples have shown that a charter cannot secure the valley.": "西班牙先前在加拉加斯建立據點的嘗試已告失敗。洛薩達提議另建一座城市，但加拉加斯及其盟友已證明，單憑特許狀無法控制這片山谷。",
  "Earn 1,000,000 doubloons in a single voyage.": "在單次航行中賺取 1,000,000 達布隆。",
  "Earn 10,000 doubloons in one voyage.": "在一次航程中賺取 10,000 達布隆。",
  "Earn 100,000 doubloons in one voyage.": "在一次航程中賺取 100,000 達布隆。",
  "East African": "東非",
  "Eastern Orthodox": "東正教",
  "Eastern Woodlands": "東部兀蘭",
  "Easy, captain. You found me out. Put the {0} away.": "別激動，船長。你識破我了。把{0}收起來吧。",
  "Eat and make merry": "吃喝玩樂",
  "Eat bamboo, avoid all work, and remain aboard": "吃竹子，不做事，繼續留在船上",
  "Eat the fish, inspect the deck, and go wherever the ship goes": "吃魚，檢查甲板，船去哪裡就去哪裡",
  "Eaton promises a commercial port and must arrive with something worth trading. Supply": "伊頓承諾建立一個商業港口，並且必須帶著一些值得交易的東西到達。供應",
  "Eats and drinks as much as one person while contributing nothing to shipboard work.": "吃喝和一個人一樣多，但對船上工作沒有任何貢獻。",
  "Eats as much as three people, drinks as much as one, and contributes nothing to shipboard work.": "吃得和三個人一樣多，喝得和一個人一樣多，對船上的活兒卻毫無貢獻。",
  "Eats two fish rations each day and contributes nothing to shipboard work. If there is no fish aboard, he catches his own.": "每天吃兩份魚糧，對船上的活兒毫無貢獻。船上沒魚時，牠會自己捕。",
  "Echigo Nagao House": "越後長尾之家",
  "Echigo's governor and deputy may dispute authority. Neither disputes my seal.": "越後守與副官或許會爭權，但沒人敢質疑我的印信。",
  "Eeeh.": "哎呀。",
  "EFFECT": "效果",
  "Eight hundred people cannot live from a military chest. Add": "八百人不能只靠軍餉過活。再添上",
  "El Dorado": "埃爾多拉多",
  "El Dorado! The legendary city of gold is real.": "黃金國！傳說中的黃金城是真實存在的。",
  "Elastic coconut-fibre rope stands up well to warm salt water.": "彈性椰子纖維繩可以很好地承受溫鹽水。",
  "Elbrus carries two rounded summits beneath a single mantle of snow. It rises broad and pale above the Caucasus rather than cutting the sky like a narrow horn.": "厄爾布魯士峰在一層雪下有兩個圓形的山峰。它寬闊而蒼白地聳立在高加索之上，而不是像一個狹窄的角一樣劃破天空。",
