  "Knotted records pass from the landing to waiting runners as coastal cargo begins its journey inland.": "當沿海貨物開始向內陸航行時，打結的記錄從著陸點傳遞到等待的跑步者。",
  "Knows when to press a bargain and when to let a factor save face.": "知道何時討價還價，何時讓港口商人保全面子。",
  "Knows where fish gather and how to bring them aboard.": "知道魚聚集的地方以及如何將它們帶上船。",
  "Kobaya": "小早",
  "Kongo": "剛果",
  "Korean": "韓國人",
  "Kosciuszko is no lonely spire. It is the highest rise in a broad, windswept country of rounded ridges, pale grass, and winter snow.": "科修斯科峰並非孤立的尖塔，而是廣闊多風的高地上最高的一處隆起。圓緩的山脊、淺色草地與冬雪鋪展四周。",
  "Kreeee!": "克里耶！",
