  "Kyoto must hear what was promised at {0}, and what was conspicuously left unsaid.": "京都必須聽到 {0} 所承諾的內容，以及明顯未說出的內容。",
  "Kyoto's offices reward a quick change of allegiance. Creditors prefer consistency.": "京都的辦公室獎勵迅速改變效忠對象。債權人更喜歡一致性。",
