  "Laced iron scales spread a blow across the body without the weight of solid plate.": "繫帶鐵鱗將打擊分散到全身，卻沒有實心板的重量。",
  "Lake sturgeon": "湖鱘",
  "Lake Titicaca": "的的喀喀湖",
  "Lake Titicaca lies beneath snow-covered Andes, yet its water spreads like a sea among the high plains. Reed boats and floating reed islands move upon its deep blue surface.": "的的喀喀湖位於冰雪覆蓋的安地斯山脈下方，但湖水卻像大海一樣在高原上蔓延。蘆葦船和漂浮的蘆葦島在其深藍色的表面上移動。",
  "Lake trout": "湖鱒魚",
