  "Leave {0} at the nearest safe shore": "把{0}留在最近的安全海岸",
  "leave for our merchants to enter Ming ports under lawful seal, customs, and the emperor's peace": "讓我們的商人在合法的印章、海關和皇帝的保佑下進入明朝的港口",
  "Leave it ashore": "把它留在岸上",
