  "Legal surrender demand": "合法移交要求",
  "Let it lie": "讓它撒謊",
  "LET IT STAY": "讓它留下來",
  "Let the bargains stand": "讓便宜貨站起來",
  "Let the chart be blank and the ocean without end. I know the mark I hunt. Towards that white shape I roll, though all the waves of the world lie between us.": "讓圖表一片空白，讓海洋無邊無際。我知道我狩獵的目標。我朝著那個白色的形狀滾動，儘管世界上所有的波浪都橫亙在我們之間。",
  "Letter of marque": "私掠許可證",
  "Letters Between Two Churches": "兩個教會之間的信",
  "Letters Between Two Fires": "兩場火災之間的信件",
  "licensed trade with Joseon": "與北韓的許可貿易",
  "Lie low in the cove": "躺在海灣的低處",
  "Liege": "列日",
  "Light, strong canvas keeps a lateen rig drawing closer to the wind.": "輕質、堅固的帆布使三角帆能更接近風。",
  "Lightning strike": "雷擊",
  "Lightning struck the ship during a storm.": "暴風雨期間，閃電擊中了船。",
