  "Port authority": "港務當局",
  "Port of Call": "停靠港",
  "Port Royal": "皇家港",
  "Port Royal has survived its first year in the sheltered basin. The Habitation, Mi'kmaq trade, and Champlain's Order of Good Cheer give Acadia a durable beginning.": "皇家港已經在庇護盆地度過了第一年。棲息地、米克馬克貿易和尚普蘭的歡樂勳章為阿卡迪亞提供了一個持久的開端。",
  "Port Royal needs grain before its second winter.": "皇家港在進入第二個冬天之前需要糧食。",
  "PORT: {0}": "連接埠：{0}",
  "Porters and brokers move between the road and anchorage, watching each new cargo for an opportunity.": "搬運工和經紀人在道路和錨地之間移動，觀察每批新貨物，尋找機會。",
  "Porters move between river barges and sea-going hulls while brokers compare cargo lists beneath the customs awnings.": "搬運工在河駁船和遠洋船體之間移動，而經紀人則在海關遮陽篷下比較貨物清單。",
  "Porters unload coastal canoes as runners leave the market with news of every unfamiliar sail.": "當跑者帶著每一次陌生航行的消息離開市場時，搬運工正在卸下沿海獨木舟。",
  "Portugal": "葡萄牙",
  "Portuguese": "葡萄牙人",
  "Portuguese Atlantic port": "葡萄牙大西洋港口",
  "Portuguese Brazil port": "葡萄牙巴西港口",
  "Portuguese Carrack": "葡萄牙卡拉克帆船",
  "Portuguese cartaz": "葡萄牙語卡塔茲",
  "Portuguese cartaz: valid": "葡萄牙語 cartaz：有效",
  "Portuguese colonial capital": "葡萄牙殖民首都",
  "Portuguese conquered city": "葡萄牙人征服的城市",
  "Portuguese crown spice monopoly": "葡萄牙皇冠香料專賣",
  "Portuguese factory and tribute station": "葡萄牙工廠和貢站",
