  "Portuguese fort and pepper factory": "葡萄牙堡和胡椒工廠",
  "Portuguese fortress and factory": "葡萄牙堡和工廠",
  "Portuguese masons are raising a fort and factory beside the clove anchorage; their flag already covers their warehouse trade.": "葡萄牙泥瓦匠正在丁香錨地旁建造一座堡壘和工廠；他們的旗幟已經覆蓋了他們的倉庫貿易。",
  "Portuguese merchant settlement": "葡萄牙商人定居點",
  "Portuguese merchants keep a privileged quarter around the new harbor, while Japanese officials retain the city.": "葡萄牙商人保留了新港口周圍的特權區，而日本官員保留了這座城市。",
  "Portuguese mission settlement": "葡萄牙使團定居點",
