  "Portuguese sugar port": "葡萄牙糖港",
  "Portuguese trading agents keep a small post here, linking Patani to their routes through Malacca and Siam.": "葡萄牙商行代理人在此經營一處小型商站，將北大年接入經馬六甲和暹羅的航線。",
  "Portuguese trading post": "葡萄牙貿易站",
  "Powder Key": "粉紅鑰匙",
  "Powder, provisions, and silence are all for sale. Doubloons in the cove: {0} db.": "灣中的達布隆：{0} DB。",
  "Powerful yew bows shoot farther across water but require skilled archers.": "強勁的紫杉木弓射程更遠，但需要熟練的弓手。",
  "Powhatan": "波瓦坦",
  "Powhatan Confederacy": "波瓦坦邦聯",
  "Praise be to God, my Hajj is complete. Now I need passage home to {0}. Carry me there and I will pay {1} db.": "感謝真主，我已完成朝覲。現在我需要搭船返回{0}的家。送我回去，我會付你{1}達布隆。",
  "Present arms and negotiate terms": "展示武器並談判條款",
  "Present the envoy to court": "將使者呈上法庭",
  "Present the guild's offering": "展示公會的產品",
  "Present the joint rebuilding plan": "提出聯合重建計劃",
  "PRESS ANY KEY TO RETURN TO START MENU": "按任一鍵返回開始功能表",
  "Price tip: {0}": "價格提示：{0}",
  "Prince": "王子",
