  "Prince-Bishopric of Liege": "列日主教侯國",
  "Prince-Bishopric of Utrecht": "烏得勒支親王主教區",
  "princes and envoys made peace. The treasury will pay the reward for": "諸侯及使節講和。財政部將給予獎勵",
  "Princes change in Targoviste. A sealed debt survives every throne.": "特爾戈維斯特的王子們發生了變化。每個王座都有一筆密封的債務。",
