  "Prisoners spared": "囚犯幸免于难",
  "private letter": "私訊",
  "Privateering authority": "私掠當局",
  "Prize cargo {0} x{1}": "獎品貨品 {0} x{1}",
  "Prize Taken": "獲獎狀況",
  "Prize transfer interrupted": "獎金轉移中斷",
  "Proceed anyway": "無論如何都要繼續",
  "Procure {0} for the mission.": "為任務取得{0}。",
  "Promise to defect for {0} db": "承諾叛逃 {0} DB",
  "Promise to fight {0} for {1}": "承諾為{1}而戰{0}",
  "Promotion has not made him less opinionated.": "晉升並沒有讓他減少固執己見。",
  "proof the first locally made matchlocks beyond the city walls": "證明城牆外第一批本地製造的火繩槍",
  "PROTECTORATE: {0} / {1}": "保護：{0} / {1}",
  "Providence needs trade cloth to honor its agreements and outfit new arrivals.": "普羅維登斯需要貿易布料來履行其協議並為新來者提供服裝。",
  "Providence now offers a refuge for conscience under civil government, founded through negotiation with Narragansett leaders rather than a Massachusetts patent.": "普羅維登斯現在為公民政府提供了良心的避難所，該避難所是透過與納拉甘西特領導人談判而不是馬薩諸塞州的專利建立的。",
  "Prrrraaaah!": "呸呸呸呸！",
  "Prudence wins. We shall admire the dog from here.": "謹慎佔了上風。我們還是站在這裡欣賞這隻狗吧。",
  "Puncak Jaya is a wall of pale, sheer rock above steaming equatorial forest, with snow and ice hidden in its highest folds. I had never seen cold and jungle pressed so close together.": "Puncak Jaya 是一堵蒼白、陡峭的岩石牆，位於熱氣騰騰的赤道森林之上，最高的褶皺中隱藏著冰雪。我從未見過寒冷和叢林如此緊密地結合在一起。",
  "Purchase {0}": "購買{0}",
  "Purchase {0}-day Portuguese cartaz": "購買 {0} 天葡萄牙卡塔茲",
  "Purchase {0}; {1} doubloon vessel trade-in": "購買{0}； {1} 金幣船隻以舊換新",
  "Purchase prices -{0}": "購買價格 -{0}",
  "Purchased {0} and brought it aboard for {1} db.": "購買了{0}並帶上船，花費{1}達布隆。",
  "Purepecha": "普雷佩查",
  "Put down the cross-staff. You are not the pilot.": "Put down the cross-staff.你不是飛行員。",
  "Put every barrel on my account. Except the wine. I believe the wine has already put me on its account.": "把每一桶都記在我的帳戶上。除了酒。我相信這酒已經讓我滿意了。",
  "Put to sea": "投入海",
  "Put to sea and fight": "出海戰鬥",
  "Put your bow {0} of {1} and watch for Captain {2}'s {3} under the black flag. She was seen there {4} days ago, carrying one scrap of a map worth twelve men's lives.": "把船頭轉向{1}{0}方向，留神{2}船長那艘懸掛黑旗的{3}。{4}日前有人在那裡看見它，船上帶著一張值十二條人命的地圖殘片。",
  "Pyramids in Nubia! How many kingdoms has the Nile carried?": "努比亞的金字塔！尼羅河流淌過多少王國？",
  "Quaker": "貴格會",
  "quays, warehouses, and houses around the new anchorage": "新錨地周圍的碼頭、倉庫和房屋",
  "Quebec needs grain before ice closes the St. Lawrence.": "在聖勞倫斯河冰封之前，魁北克需要糧食。",
  "Quebec now secures New France at the narrow passage of the St. Lawrence, sustained by shipping, fur trade, and alliances with the Innu, Algonquin, and Wendat.": "魁北克如今守住聖羅倫斯河的狹窄航道，成為新法蘭西的支柱；航運、毛皮貿易以及與因努人、阿爾岡昆人和溫達特人的聯盟支撐著這裡。",
  "Queen": "女王",
  "Queen {0}": "女王 {0}",
  "Quest cargo source": "任務貨物來源",
  "Quest cargo: {0}": "任務貨物：{0}",
  "Quest document": "任務文件",
  "Quicker-firing, heavier broadside guns can decide the exchange before the enemy reloads.": "射速更快、重量更重的舷側火砲可以在敵人重新裝彈之前決定交鋒。",
  "Quietly now. Here is the chest. Get it aboard and take it to our friends before anyone starts asking questions.": "現在靜靜地。這是胸部。在有人開始提問之前將其帶上車並交給我們的朋友。",
  "R ALT": "丙氨酸轉氨酶",
  "R CTRL": "右 CTRL",
  "R META": "元數據",
  "R SHIFT": "右移",
  "Raccoon": "浣熊",
  "RACE TO NINGBO": "奔赴寧波",
  "Ragusa": "拉古薩",
  "Ragusa pays every great power for peace. Your family merely added another instalment.": "拉古薩向各大強權付錢求和。你的家族不過是又添了一筆分期債款。",
  "Ragusan": "拉古桑",
  "Raichur's victory procession was splendid. I noticed your paymaster absent from it.": "雷丘爾的勝利遊行非常精彩。我注意到你的出納員不在場。",
  "Rainier loomed above the inland waters, a massive white volcano cut by rivers of ice. Even at great distance it made the forested ridges before it seem small.": "雷尼爾山高踞內陸水域之上，巨大的白色火山被冰河切割。即使遠在天邊，它仍令前方的森林山脊顯得渺小。",
  "Raise Our Colors": "提高我們的色彩",
  "Raleigh has a patent for Virginia and means to plant families, not another hungry garrison. Roanoke offers a known harbor, though the Chesapeake was the intended destination.": "羅利擁有維吉尼亞州的專利，可以種植家庭，而不是另一個飢餓的駐軍。羅阿諾克提供了一個著名的港口，儘管切薩皮克是預定的目的地。",
  "Ramadan begins today. From dawn until sunset I will fast while strength allows.": "齋月從今天開始。從黎明到日落，只要體力允許，我就會禁食。",
  "Ramadan begins. I will keep the fast while strength allows, and meet sunset with gratitude.": "齋月開始。我會在力氣允許的情況下守齋，感恩地迎接日落。",
  "Ramadan begins. We shall take food before dawn and break our fast together after sunset.": "齋月開始。我們將在黎明前進食，並在日落後一起開齋。",
  "Re-form the expedition": "重新組成探險隊",
  "Reach {0}": "達到 {0}",
  "Read it, then. A river punishes captains who only watch the banks.": "那就讀吧。河流懲罰只守望河岸的船長。",
  "Reads shoals and handles a net with confidence.": "自信地閱讀淺灘並處理網路。",
  "READY FOR LAUNCH": "準備下水",
  "REALIZED P/L {0} DB": "已實現利潤或虧損 {0} DB",
  "REBELLION: {0} / {1}": "叛逆：{0} / {1}",
  "REC {0}:{1}": "REC {0}：{1}",
  "Recalled crown commission: {0}": "召回皇家委員會：{0}",
  "Receive the answer": "收到答覆",
  "received shipyard sale shares": "收到船廠出售股份",
  "Recife has become the reef-sheltered warehouse port of Pernambuco. Sugar comes down from the mills, and Atlantic hulls crowd the channel.": "累西腓已成為伯南布哥州的珊瑚礁倉庫港口。糖從工廠運來，大西洋的船體擠滿了海峽。",
  "Recife needs a full sugar cargo to prove the new harbor can pay.": "累西腓需要滿載的糖貨來證明新港口有能力支付費用。",
  "Recite the voyage with the navigators": "與航海家一起朗誦航程",
  "Recommend a stricter register": "建議更嚴格的註冊",
  "Reconstructed ash and yew bows complete the longship's fighting equipment.": "重建的白蠟樹和紫杉弓完善了長船的戰鬥裝備。",
  "Recover the silver cup": "奪回銀杯",
  "Recovered": "已恢復",
  "Recovered all {0} pieces of Captain {1}'s map, found the island, and fought the old crew home.": "取回了船長{1}地圖的所有{0}碎片，找到了島嶼，並與老船員戰鬥回家。",
  "Red Lantern Haven": "紅燈籠天堂",
  "REDUCE CREW": "削減船員",
  "Reef fish": "礁魚",
