  "Rhinoceros": "犀牛",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry": "羅德已經倒下了，但騎士團的誓言卻沒有。尊者希望你攜帶",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat": "羅德已經倒下了，但騎士團的誓言卻沒有。教宗陛下希望您向西班牙國王兼皇帝查理提出請願書，要求授予馬耳他作為新席位",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}": "羅德已經倒下了，但騎士團的誓言卻沒有。教宗陛下希望您向西班牙國王兼皇帝查爾斯提交一份請願書，要求授予馬耳他一個新席位{0}",
  "Rhodes has fallen, but the Order's vows have not. His Holiness would have you carry a petition to Charles, King of Spain and Emperor, that Malta be granted as a new seat{0}.": "羅德已經倒下了，但騎士團的誓言卻沒有。教宗陛下希望您向西班牙國王兼皇帝查爾斯提交一份請願書，要求授予馬耳他一個新席位{0}。",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and": "羅德迷失在我們身後。在比爾古，我們將再次舉起八角十字架，",
  "Rhodes is lost behind us. At Birgu we shall raise the eight-pointed cross again, and make a fortress of our exile.": "羅德迷失在我們身後。在比爾古，我們將再次舉起八角十字架，為我們的流亡者建造一座堡壘。",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders.": "羅德島仍然矗立在奧斯曼海前，但勇氣無法滿足其守衛者的需求。",
  "Rhodes still stands before the Ottoman sea, but courage cannot feed its defenders. Carry {0} and a Papal nuncio to {1}.": "羅德島仍然矗立在奧斯曼海前，但勇氣無法滿足其守衛者的需求。將{0}和教宗大使帶到{1}。",
