  "Santiago de Leon de Caracas now holds the valley, and the Indian name Caracas has already outlasted the one in the charter.": "聖地亞哥·德·萊昂·德·加拉加斯現在佔據了這個山谷，而印度名稱“加拉加斯”的壽命已經超過了憲章中的名稱。",
  "Sao Paulo de Luanda has become Portugal's fortified Angolan port. Its Atlantic wealth comes from inland war and the slave trade.": "聖保羅-羅安達已成為葡萄牙在安哥拉的堅固港口。它的大西洋財富來自內陸戰爭和奴隸貿易。",
  "Sao Sebastiao cannot secure Guanabara without more powder.": "如果沒有更多的火藥，聖塞巴斯蒂昂就無法保衛瓜納巴拉。",
  "Sao Sebastiao has secured Guanabara Bay for Portugal. Around the old redoubt, Rio de Janeiro is becoming a true port.": "聖塞巴斯蒂昂已為葡萄牙確保了瓜納巴拉灣。在舊堡壘周圍，裡約熱內盧正在成為一個真正的港口。",
