  "Ships": "船舶",
  "Ships and mills cannot run on promises. Complete the harbor stores with": "船舶和工廠不能兌現承諾。完成港口商店",
  "Ships or port attacked": "船只或港口遭到袭击",
  "Ships, carts, and warehouse crews crowd the waterfront; every arrival changes some merchant's plans.": "船隻、手推車和倉庫工作人員擠滿了海濱。每次到來都會改變一些商人的計劃。",
