  "Shogun {0}": "幕府將軍{0}",
  "Shogun Ashikaga Yoshiharu has sealed an order for the western sea lords. Carry it from Kyoto to Yamaguchi before private war answers first.": "將軍足利義治向西方海王下達了命令。在私人戰爭首先出現之前將其從京都運到山口。",
  "shogunal messenger": "幕府使者",
  "Shona": "紹納人",
  "Shoni": "紹尼",
  "Shoni House": "紹尼之家",
  "shore battery": "岸電",
  "Shore Leave": "上岸休假",
  "Shore Party Kit": "岸上派對套件",
  "Short haul": "近程航行",
  "Show mercy and release": "開恩並釋放",
  "Shrine and Temple Together": "神社和寺廟在一起",
  "shrine keeper": "神社守護者",
  "Shrine-temple donors' gift": "神社寺廟捐贈者的禮物",
  "shrine-temple steward": "神社寺廟管事",
  "Sichuan": "四川",
  "Sickness and poor water threaten Winthrop's crowded Charlestown camp. Blackstone points them across the river to Shawmut's spring.": "疾病和缺水威脅著溫斯洛普擁擠的查爾斯敦營地。布萊克斯通指引他們過河前往肖姆特的泉水。",
  "Sight, height, and speed joined into one method. Your bearings may even let us estimate how far above the ground it hunted.": "視線、高度和速度合而為一。您的方位甚至可以讓我們估計它在離地面多遠的地方搜尋。",
  "Sigiriya": "錫吉里亞",
  "Sigiriya rises sheer above the forest. A stair once passed between the paws of a colossal lion, climbing toward gardens and a fortress balanced upon the summit.": "錫吉里耶高聳於森林之上。曾經有一段樓梯從一隻巨大獅子的爪子之間穿過，爬向花園和山頂上的一座堡壘。",
  "Signoria": "執政團",
  "Signoria {0}": "執政團{0}",
  "Sikh": "錫克人",
  "Silk, official seals, and calendars travel outward; sulfur and island wares return. Ceremony keeps the sea road in order.": "絲綢、官印和曆法向外傳送；硫磺與島貨運回。禮儀維繫著海路秩序。",
  "Silkscreen": "絲網印刷",
  "simple houses along the Moshassuck and a common landing": "莫沙薩克河沿岸的簡單房屋和公共平台",
  "Since I was a child, I have dreamed of seeing the whole world with my own eyes: every impossible mountain, ancient city, and shore beyond the horizon. {0}": "從小我就夢想著親眼看到整個世界：每一座不可能的山峰、每一座古城、每一座地平線之外的海岸。 {0}",
  "Since your last visit, we sold {0}.": "自您上次造訪以來，我們已售出 {0}。",
  "Sing with the sangat": "與桑加特一起唱歌",
  "Sinhalese": "僧伽羅人",
  "Sink or force the surrender of an enemy ship.": "擊沉或迫使敵艦投降。",
  "Sit down, captain. I shall separate geography from wine before adding either to the atlas.": "坐下吧，隊長。在将地理和葡萄酒添加到地图集之前，我将把它们分开。",
  "Sit with the responsum court": "與響應法庭一起坐在一起",
  "Skilled Chef": "熟練的廚師",
  "Skilled Fisher": "熟練的漁夫",
  "Skilled Negotiator": "熟練的談判者",
  "SKILLS": "技能",
  "Slavic": "斯拉夫人",
  "Sloth": "樹懶",
  "Slowness may be an adaptation rather than a defect. I shall write that cautiously; scholars are very fond of mistaking unfamiliar success for failure.": "缓慢可能是一种适应而不是一种缺陷。我会谨慎地写下这一点；学者们很喜欢把不熟悉的成功误认为是失败。",
  "Small Cog": "小型柯克船",
  "Small hull, small target. Think grateful thoughts.": "船体小，目标小。思考感恩的想法。",
  "Small Iceberg": "小冰山",
  "Small Junk": "小型福船",
  "Smith": "鐵匠",
  "Smoke that thunders indeed! The whole river vanishes into mist.": "確實是煙霧繚繞！整條河消失在霧氣之中。",
  "Smolensk changed hands. This deed did not.": "斯摩棱斯克易主。這個行為沒有。",
  "Smuggler's Rest": "走私者休息處",
  "Snow above the equatorial plains: precisely the sort of truth a comfortable scholar would dismiss as sailors' nonsense. Your careful account will make disbelief harder.": "赤道平原上空有雪：正是这样的事实，一个安逸的学者会认为是水手的胡言乱语。你仔細的敘述會讓你更難以相信。",
  "So": "所以",
  "So did I. The voyage would never have meant half as much without you, and I want every year that follows to be ours.": "我也是。如果沒有你，這次航行的意義永遠不會減少一半，我希望接下來的每一年都是我們的。",
  "Sō envoy": "宗使",
  "So House": "故居",
  "So many merchants came in today that every warehouse keeper claims a shortage.": "今天進來的商家太多了，每個倉庫老闆都聲稱缺貨。",
  "So the armor is hide, not shell, and its hearing compensates for its sight. That corrects three illustrated manuscripts on my shelf at once.": "所以盔甲是兽皮，而不是外壳，它的听觉弥补了它的视觉。这同时纠​​正了我书架上的三份插图手稿。",
  "So the river that feeds Egypt gathers its strength beneath another sky. Put every inlet you saw upon the chart; the beginning of a river can explain half a continent.": "因此，滋养埃及的河流在另一个天空下积聚了力量。将您看到的每个入口写在海图上；一条河流的起点可以解释半个大陆。",
  "So the tales are true: Captain {0}'s treasure is aboard.": "所以這些故事是真的：{0}船長的寶藏在船上。",
  "So the tales are true: Captain {0}'s treasure is aboard. Heave to. We will take the hoard and leave your crew their lives.": "所以這些故事是真的：{0}船長的寶藏在船上。舉起。我們將拿走這些寶藏，並留下你們船員的生命。",
  "So thirsty... We need fresh water.": "太渴了...我們需要淡水。",
  "Sold {0} for {1} db. P/L {2}.": "已售出 {0}，價格為 {1} DB。獲利或虧損{2}。",
  "Sold {0} x{1} for {2} db. P/L {3}.": "已售出 {0} x{1}，價格為 {2} DB。獲利或虧損{3}。",
  "soldiers campaigning inland from the coast": "士兵從海岸向內陸作戰",
  "soldiers facing French guns and Tamoio canoes": "面對法國槍枝和塔莫約獨木舟的士兵",
  "Somali": "索馬里人",
  "Something in the porcelain crate rattled. Lash it again before profit becomes crockery.": "瓷箱里有什么东西发出嘎嘎声。在利润变成陶器之前再次鞭打它。",
  "Somewhere beyond this water, the white whale still breathes. So do I.": "這片海域之外，白鯨仍在呼吸。我也一樣。",
