  "Spain": "西班牙",
  "Spain has lost her ports, but many Spaniards still hunger for Peru. Panama remembers our pact. Give me until dawn to replace the fallen; we will carry the Crown in our hearts.": "西班牙失去了港口，但許多西班牙人仍渴望秘魯。巴拿馬記得我們的盟約。給我時間到黎明，我會補上陣亡者的空缺；我們會把王冠的事業銘記於心。",
  "Spanish": "西班牙人",
  "Spanish American trade license": "西屬美洲貿易許可證",
  "Spanish Andean town": "西班牙安地斯小鎮",
  "Spanish attack is a real possibility from the first season. Bring": "從第一個航季起，西班牙就可能發動攻擊。帶上",
  "Spanish Chilean port": "西班牙在智利的港口",
  "Spanish conquered capital": "西班牙征服首都",
  "Spanish conquered city": "西班牙征服的城市",
  "Spanish Florida colony": "西班牙佛羅裡達殖民地",
  "Spanish Indies monopoly": "西班牙在美洲的貿易壟斷",
  "Spanish Manila now commands the bay from beside the old Tagalog port, drawing Chinese junks and Pacific shipping into a new imperial capital.": "西班牙馬尼拉如今在舊他加祿港旁控制著海灣，吸引中國帆船和太平洋航運駛向這座新的帝國首都。",
  "Spanish mercury boomtown": "西班牙汞礦繁榮城鎮",
