  "Speak with {0}": "與 {0} 交談",
  "Speak with Exeter's canal commissioner": "与埃克塞特运河专员交谈",
  "Speak with the {0}": "與 {0} 交談",
  "Speak with the {0} before they go ashore.": "在{0}上岸前與他們交談。",
  "Speak with the adelantado": "與阿德蘭塔多交談",
  "Speak with the cook": "與廚師交談",
  "Speak with the gunsmith": "與槍匠交談",
