  "SPECIALIST": "專家",
  "Sperm whale": "抹香鯨",
  "SPERM WHALE RAM -{0} HULL": "抹香鯨撞擊 -{0} 船體",
  "Speyer": "施派爾",
  "Spice of Life": "生活調味品",
  "Spice Trader": "香料商人",
  "Splendid! You have recorded every creature in these waters. The full game opens distant oceans and many blank pages in my book.": "太好了！你已記錄下這片海域的所有生物。完整版還會開放遙遠的海洋，讓我的記錄簿添上許多新頁。",
  "Square-Rigged Caravel": "橫帆卡拉維爾帆船",
  "St. Augustine endured where earlier Spanish attempts failed. It is a permanent planned town and naval base in Florida.": "세인트오거스틴은 이전 스페인의 시도가 실패한 곳에서 살아남았습니다. 플로리다에 계획적으로 세운 영구 도시이자 해군 기지입니다.",
  "St. Augustine needs grain before storms or war cut off the harbor.": "聖奧古斯丁在風暴或戰爭切斷港口之前需要糧食。",
  "St. George's has turned the Sea Venture's emergency refuge into England's permanent Bermuda capital.": "聖喬治把海上冒險號的緊急避難地發展成英格蘭在百慕達的永久首府。",
  "St. George's needs iron; cedar is plentiful, but the island cannot grow nails or axes.": "聖喬治需要鐵。島上盛產雪松，但釘子和斧頭可不是樹上長出來的。",
  "St. John's already hosts Basque, Portuguese, French, and English fishers each season. Gilbert's colony died with him at sea; we mean to revive it.": "聖約翰每年都有巴斯克、葡萄牙、法國和英格蘭漁民前來。吉爾伯特葬身海上後，他的殖民地也隨之消亡；我們要讓它重現。",
  "St. John's needs salt before the cod fleets arrive.": "在鳕鱼船队到达之前，圣约翰需要盐。",
  "St. John's now has permanent stores and winter residents serving a fishery that was international long before England claimed it.": "聖約翰如今有了常設倉儲和越冬居民，服務這片早在英格蘭宣稱擁有之前就已屬於國際漁場的海域。",
  "stages, flakes, boats, and winter houses": "漁棚、晾魚架、船隻和冬季住房",
  "stakes, bridgework, and frames around the new plaza": "新廣場周圍的木樁、橋樑和框架",
  "Stand down! This vessel carries an accredited imperial commissioner.": "站住！這艘船載有一位經過認可的帝國專員。",
  "Stand down! This vessel carries royal dispatches and colonial returns.": "站住！這艘船承載著皇家的急件和殖民地的回報。",
  "Stand down! This vessel carries the shogun's sealed order.": "站住！這艘船承載著幕府將軍的密封命令。",
  "Stand down. The challenge has ended, and we are breaking off.": "停火！交戰已經結束，我們這就撤離。",
  "Stand off. Our guns are trained on you.": "保持距離。我們的火砲正對準你們。",
  "Stand witness before the ancestors": "在祖先面前作見證",
  "Standard ordnance": "標準軍械",
  "Standing adjustment": "聲望變化",
  "Start the assault": "開始進攻",
  "Start the raid": "開始突襲",
  "STARVATION": "飢餓",
  "Stay your weapons! This ship carries articles of allegiance under diplomatic seal.": "別開火！這艘船載有加蓋外交封印的效忠文書。",
  "Steer well enough to return, and perhaps you can ask her.": "好好驾驶就可以回来了，也许你可以问问她。",
  "Step into the cove": "走進海灣",
  "Steps to Shatrunjaya": "通往 Shatrunjaya 的步驟",
  "Still need {0}": "仍然需要 {0}",
  "Still need {0} {1};": "還需要 {0} {1}；",
  "Still need {0} {1}; hold has {2}.": "還差{0}{1}；貨艙內有{2}。",
  "Still need {0}.": "仍然需要 {0}。",
  "Still need: {0}.": "仍然需要：{0}。",
  "STOCK": "可用庫存",
