  "STOCK {0}/{1} LEVELS{2}": "庫存等級 {0}/{1}{2}",
  "Stockholm yielded more readily than your royal paymaster.": "斯德哥尔摩比你的皇家金主更容易让步。",
  "Stone, water, and ceremony meet here. The vast well shows how the city endured; its carvings reveal what the people feared and honored.": "石、水與儀式在此交會。巨大的天然井見證了這座城市如何延續；雕刻則揭示了人們敬畏與崇奉之物。",
  "Stonehenge": "巨石陣",
  "Stonehenge! Who raised these stones, and what did they see in the sky?": "巨石陣！是誰建起了這些巨石？他們曾在天空中看見什麼？",
  "Storage level {0}/{1}": "倉儲等級{0}/{1}",
  "Stores": "物資",
  "STORES": "物資",
  "STORM": "風暴",
  "STORM {0}%": "風暴 {0}%",
  "STORM DAMAGE -{0} HULL": "風暴損壞 -{0} 船體",
  "STORM PASSED - SAFE TO SAIL": "風暴過去－安全航行",
  "Storm weather. Remain in shelter if your hull is doubtful.": "暴風雨將至。若船體狀況不佳，請留在避風處。",
  "STRAY SHOT - HOLD YOUR FIRE": "流彈——停止射擊",
  "STRAY SHOT: {0} STANDING {1}": "流彈：{0} 聲望 {1}",
  "study the lock, breech screw, and proportions of the Portuguese pieces": "研究葡萄牙火炮的炮閂、炮尾螺栓和尺寸比例",
  "Study the reconstructed longship at sea": "研究重建的海上長船",
  "Sturdy Barrels": "堅固的桶",
  "Submit the forged papers": "提交偽造的文件",
  "Success. I have petted the dog and retained all ten fingers.": "成功。我摸到了狗，十根手指也都還在。",
  "Successfully hunt a whale.": "成功捕鯨。",
  "Succession": "繼承",
  "Such a warrant requires the council's seal, Captain. Present your petition at {0}.": "船長，這份授權須加蓋議會印章。請到{0}遞交申請。",
  "Sugarloaf guards the entrance and French sails lie deeper in the bay. We will plant Sao Sebastiao here as Portugal's base for the coming fight.": "舒格洛夫山守著海灣入口，法國艦船停在更深處。我們要在此建立聖塞巴斯蒂昂據點，作為葡萄牙迎戰的基地。",
