  "Valdivia wants a southern base at Penco Bay. This is Mapuche country; the proposed town is a frontier fort in an active war.": "瓦爾迪維亞希望在彭科灣建立一個南方基地。這是馬普切人的國家；擬議的城鎮是一場激烈戰爭中的邊境堡壘。",
  "Valid against war enemies": "對戰爭敵人有效",
  "Vassal agreement": "附庸协议",
