  "Venetian": "威尼斯人",
  "Venetian fondaco": "威尼斯方達科",
  "Venetian merchant quarter": "威尼斯商業區",
  "Venetian merchants lodge and trade through their fondaco under the eye of their consul.": "威尼斯商人在領事的監督下透過他們的方達科住宿和交易。",
  "Venice": "威尼斯",
  "Venice called for one loan after another while the mainland burned. Cambrai ended; our obligations did not.": "當大陸被燒毀時，威尼斯要求一筆又一筆貸款。康布雷結束；我們的義務沒有。",
  "Very well. But I am not listing it as an able seaman.": "好吧。但我不會把牠列為合格水手。",
  "Very well. He may stay, but somebody keep him out of the fish barrel.": "好吧，牠可以留下，但派人看好，別讓牠鑽進魚桶。",
  "Very well. Lock the larder, count the spoons, and do not call him an able seaman.": "很好。鎖上食品儲藏室，數數勺子，不要稱他為能幹的水手。",
  "Very well. The {0} will remain available in the equipment store if you change your mind.": "很好。如果您改變主意，{0} 仍將在裝置商店中提供。",
  "Very well. The commission remains available while {0} is at war. Ask me if you reconsider.": "很好。只要{0}仍在交戰，這項軍事委任仍可承接。改變主意就來找我。",
